   "id": "CFW-M-030",
   "class": "CFW-M",
   "label": "\"Recourse\" names two objects on two axes: the ability to change an outcome from a fixed model, and a legal or administrative remedy. An explanation right is neither an appeal nor compensation, and a no-fault liability cascade is neither a culpability nor an answerability mechanism.",
